# 第二步：主网变体（@main）——EVM 文案改为非托管；Solana 提示保持原有 devnet / 主网两套
import re, subprocess
for f in sorted(os.listdir(D)):
    if not f.endswith('.json'): continue
    p = os.path.join(D, f); d = json.load(open(p, encoding='utf-8'))
    for k in ['wal.evmHint', 'wish.payEvm']:
        if k + '@main' in d: d[k + '@main'] = d[k]
    if 'mode.evm@main' in d: d['mode.evm@main'] = re.sub(r'\s*·\s*Solana\s*\{sol\}', '', d['mode.evm@main']).replace('{sol}', '').rstrip(' ·')
    json.dump(d, open(p, 'w', encoding='utf-8'), ensure_ascii=False, indent=2); open(p, 'a').write('\n')
